package finance.client;import finance.network.GovernanceResponsePacket;import java.util.concurrent.atomic.AtomicLong;public final class GovernanceClientCache{public enum State{NOT_REQUESTED,LOADING,READY,SLOW}public record Entry(State state,long id,long at,GovernanceResponsePacket data){}private static final AtomicLong SEQ=new AtomicLong();private static Entry e=new Entry(State.NOT_REQUESTED,0,0,null);private GovernanceClientCache(){}public static long begin(){long id=SEQ.updateAndGet(x->x==Long.MAX_VALUE?1:x+1);e=new Entry(State.LOADING,id,System.currentTimeMillis(),null);return id;}public static void accept(GovernanceResponsePacket p){if(p!=null&&p.requestId()==e.id())e=new Entry(State.READY,p.requestId(),0,p);}public static Entry get(){if(e.state()==State.LOADING&&System.currentTimeMillis()-e.at()>3000)e=new Entry(State.SLOW,e.id(),e.at(),e.data());return e;}public static void clear(){e=new Entry(State.NOT_REQUESTED,0,0,null);}}
